package com.fitconnect.payment.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity public class Payment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true) private String paymentReference; private Long bookingId; private String bookingReference; private Long userId; private BigDecimal amount; @Enumerated(EnumType.STRING) private PaymentMethod paymentMethod; private String cardLastFour; private String transactionId; private LocalDateTime paymentDate; @Enumerated(EnumType.STRING) private PaymentStatus status;
protected Payment(){} public Payment(Long bookingId,String bookingReference,Long userId,BigDecimal amount,PaymentMethod method,String lastFour,String transaction){this.bookingId=bookingId;this.bookingReference=bookingReference;this.userId=userId;this.amount=amount;this.paymentMethod=method;this.cardLastFour=lastFour;this.transactionId=transaction;this.paymentDate=LocalDateTime.now();this.paymentReference="PAY-"+String.format("%05d",Math.abs(bookingId));this.status=amount.compareTo(new BigDecimal("100"))<0?PaymentStatus.SUCCESS:PaymentStatus.FAILED;}
public Long getId(){return id;} public String getPaymentReference(){return paymentReference;} public Long getBookingId(){return bookingId;} public String getBookingReference(){return bookingReference;} public Long getUserId(){return userId;} public BigDecimal getAmount(){return amount;} public PaymentMethod getPaymentMethod(){return paymentMethod;} public String getCardLastFour(){return cardLastFour;} public String getTransactionId(){return transactionId;} public LocalDateTime getPaymentDate(){return paymentDate;} public PaymentStatus getStatus(){return status;} public void refund(){if(status==PaymentStatus.SUCCESS)status=PaymentStatus.REFUNDED;}
}
